                ],
                "reason": "decouple(release-infra): a chrome-release composite action in the core .github/ tree; being vendored out (#276)"
              },
              {
                "path": "extending.md",
                "to": [
                  "packs/grow_with_claudinite"
                ],
                "reason": "inherent(#385): the engine map documents where the adoption-interview machinery lives now that it is bundled in the adoption skill"
              }
            ]
          }
        ]
      }
    }
  ],
  "accept": [
