import json, sys, datetime

def ts(s):
    return datetime.datetime.fromisoformat(s.replace('Z','+00:00'))

def run(path, mode='full'):
    entries=[]
    with open(path) as f:
        for line in f:
            line=line.strip()
            if not line: continue
            try: entries.append(json.loads(line))
            except: pass
    # map tool_use_id -> (name, input, assistant_ts)
    tu={}
    out=[]
    first=None; last=None
    tool_time=0.0
    durations=[]
    for e in entries:
        t=e.get('timestamp')
        if t:
            tt=ts(t)
            if first is None or tt<first: first=tt
            if last is None or tt>last: last=tt
        msg=e.get('message') or {}
        role=msg.get('role')
        content=msg.get('content')
        if isinstance(content,str): content=[{'type':'text','text':content}]
        if not isinstance(content,list): content=[]
        if role=='assistant':
            for c in content:
                if c.get('type')=='text':
                    txt=c.get('text','').strip()
                    if txt: out.append(('A', t, txt))
                elif c.get('type')=='tool_use':
                    tu[c.get('id')]=(c.get('name'), json.dumps(c.get('input'))[:400], t)
        elif role=='user':
            for c in content:
                if c.get('type')=='text':
                    txt=c.get('text','').strip()
                    if txt: out.append(('H', t, txt))
                elif c.get('type')=='tool_result':
                    tid=c.get('tool_use_id')
                    name,inp,att=tu.get(tid,('?','',None))
                    dur=None
                    if att and t:
                        dur=(ts(t)-ts(att)).total_seconds()
                        tool_time+=dur
                        durations.append((dur,name,inp))
                    res=c.get('content')
                    if isinstance(res,list):
                        res=' '.join(x.get('text','') for x in res if isinstance(x,dict))
                    res=str(res)
                    err=c.get('is_error')
                    out.append(('T', t, f"[{dur:.0f}s] {name} {inp}" + (" ERROR" if err else "") + "\n   -> " + res[:300].replace('\n',' | ')))
    total = (last-first).total_seconds() if first and last else 0
    print(f"### {path.split('/')[-1]}")
    print(f"span {first} -> {last}  wall={total:.0f}s  tool_wall={tool_time:.0f}s ({100*tool_time/total if total else 0:.0f}%)  entries={len(entries)}")
    print("--- top 12 slowest tool calls ---")
    for d,n,i in sorted(durations, reverse=True)[:12]:
        print(f"  {d:7.0f}s {n} {i[:160]}")
    print("--- transcript ---")
    for kind,t,txt in out:
        if kind=='H':
            print(f"\n@@HUMAN {t}:\n{txt[:4000]}\n")
        elif kind=='A':
            print(f"[A {t}] {txt[:1200]}")
        elif mode=='full':
            print(f"  {txt[:500]}")

if __name__=='__main__':
    run(sys.argv[1], sys.argv[2] if len(sys.argv)>2 else 'full')

